use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut prefix_sums = Vec::new();
    let mut sum = 0;
    for &item in arr {
        sum += item.as_i64().unwrap();
        prefix_sums.push(serde_json::Value::from(sum));
    }
    Value::Array(prefix_sums)
}
